5	/**
6	 * Derives the Konnect region string from a control plane endpoint URL.
7	 * e.g. "https://abc123.us.cp0.konghq.com" → "us"
8	 * Falls back to "us" for unrecognised or malformed values.
9	 */
10	export function extractRegionFromEndpoint(endpoint: string): string {
11	  try {
12	    const hostname = new URL(endpoint).hostname;
13	    const parts = hostname.split('.');
14	    // Pattern: <id>.<region>.cp0.konghq.com
15	    if (parts.length >= 4 && parts[parts.length - 2] === 'konghq' && parts[parts.length - 1] === 'com') {
16	      if (parts[parts.length - 3] === 'cp0') {
17	        return parts[parts.length - 4];
18	      }
19	      console.warn(`[konnect] Unexpected endpoint hostname format, defaulting region to "us": ${hostname}`);
20	    }
21	  } catch {
22	    console.warn(`[konnect] Malformed control_plane_endpoint, defaulting region to "us": ${endpoint}`);
23	  }
24	  return 'us';
25	}
